/* The festival this planner is pointed at.
 *
 * Everything that differs between one festival's planner and another's lives
 * here: the name, the city, the data file, the storage namespace, the partner
 * links and the theme class. The page code below it reads this descriptor and
 * names no festival of its own, so a third festival is a new descriptor, a new
 * theme block in the stylesheet, and its own scraped catalogue — not a third
 * copy of the page.
 *
 * Pure data plus two link builders: no DOM, no fetch.
 */

import { israelRailLink, israelTravelLink, stayLink } from "../shared/affiliates.js";

export const FESTIVAL = {
  id: "jerusalem-comedy",
  /* What the header renders. `wordmark` is split so the accent colour lands on
     the second half, the way EdFringe|Now does. */
  wordmark: ["Jerusalem", "Comedy"],
  navLabel: "Jerusalem",
  title: "Jerusalem Comedy Festival planner",
  /* The programme's own language. Every string that comes out of the catalogue
     is tagged with it, so a browser lays Hebrew out right-to-left and picks a
     font that has the glyphs. */
  lang: "he",
  dir: "rtl",
  city: "Jerusalem",
  /* The catalogue the scrape writes. Relative to this page, because the site is
     served from a subpath and a root-relative URL would resolve above it. */
  dataUrl: "../data/jerusalem/shows.json",
  /* The page's own corner of localStorage. Sharing the planner's code must
     never mean sharing its stored list, so every key this page writes starts
     here and the Edinburgh planner's keys are never touched. */
  storagePrefix: "jerusalemPlan.",
  /* How the site's own home page and Edinburgh planner are reached from here. */
  siteNav: [
    { href: "../", label: "Now" },
    { href: "../plan/", label: "Plan" },
  ],
};

/* Somewhere to sleep for the nights of the trip — Booking.com's Hebrew edition,
 * in shekels, which is what "the local Booking.com" means for Jerusalem. */
export function festivalStayLink(checkinISO, checkoutISO) {
  return stayLink({
    checkinISO,
    checkoutISO,
    city: FESTIVAL.city,
    locale: "he",
    currency: "ILS",
    label: "edfringenow-jerusalem-night",
  });
}

/* Getting here. Two links, deliberately: the paid airport transfer, and the
 * train beside it — Israel Railways pays nothing and is still usually the right
 * answer from Ben Gurion, and a planner that hid it to protect a commission
 * would be worth less than one that didn't. */
export function festivalTravelLinks() {
  return [israelTravelLink(), israelRailLink()];
}
/* The Jerusalem catalogue, adapted to the shape the planning engine consumes.
 *
 * `data/jerusalem/shows.json` is the scrape's own file (see
 * scraper/jerusalem/); the engine in plan/lib/ speaks the Edinburgh catalogue's
 * vocabulary. This module is the one place the two meet, so the page below it
 * never sees a raw scrape record and the engine never learns a second shape.
 *
 * Pure apart from the fetch: everything else is a rename.
 */

/* Availability semantics for a festival that publishes none.
 *
 * This programme has no live ticket feed, no sold-out signal and no
 * cancellations — the source simply says a performance exists. The engine reads
 * `status` through the Edinburgh denylist, so a performance is marked with the
 * status that means what is actually true here: it is on sale, or it is free to
 * attend. Neither is in the denylist, so both schedule. Inventing a
 * "TICKETS_AVAILABLE" for a free late-night with no ticket at all would be a
 * claim the source never made.
 */
const ON_SALE = "TICKETS_AVAILABLE";
const FREE = "FREE_NON_TICKETED";

/**
 * Fetch and adapt the festival catalogue.
 * @param {string} url the catalogue's URL, relative to the page
 * @returns {Promise<{festival: object, venues: Map, shows: object[], categories: Array}>}
 */
export async function loadCatalogue(url) {
  const response = await fetch(url, { cache: "no-cache" });
  if (!response.ok) throw new Error(`${response.status} ${response.statusText} for ${url}`);
  return adaptCatalogue(await response.json());
}

/** The pure half of loadCatalogue, so it can be exercised without a network. */
export function adaptCatalogue(raw) {
  const venues = new Map();
  for (const venue of raw.venues || []) {
    venues.set(venue.code, venue);
  }

  const shows = (raw.shows || []).map((show) => {
    const venueCodes = [...new Set(show.performances.map((p) => p.venue).filter(Boolean))];
    // Every show in this programme plays one venue, but the shape allows more,
    // so the engine is given the first and the lane names all of them.
    const venueCode = venueCodes[0] || null;
    const venue = venueCode ? venues.get(venueCode) : null;
    return {
      slug: show.slug,
      title: show.title,
      url: show.url,
      // The engine draws a genre emoji and the CSV exports a Genre column; the
      // festival's own categories are what it has to say there.
      genre: show.categoryNames[0] || null,
      genreSlug: show.categories[0] || null,
      blurb: show.description || null,
      // Four shows publish no running time. Left null, never defaulted: the
      // scheduler reads it to decide whether two shows clash, and a guessed
      // length would invent a clash or hide one.
      duration: show.duration,
      venue: venueCode,
      venueName: venue ? venue.name : null,
      venueNames: venueCodes.map((code) => (venues.get(code) || {}).name).filter(Boolean),
      performances: show.performances.map((p) => ({
        date: p.date,
        start: p.start,
        status: p.free ? FREE : ON_SALE,
        soldOut: false,
        ticketUrl: p.ticketUrl,
        free: p.free,
        venue: p.venue,
      })),
    };
  });

  return {
    festival: raw.festival,
    venues,
    shows,
    categories: (raw.categories || []).map(([slug, name]) => ({ slug, name })),
  };
}

/** Every night the programme uses, ascending — the grid's columns. */
export function festivalDates(shows) {
  return [...new Set(shows.flatMap((s) => s.performances.map((p) => p.date)))].sort();
}

/** `{ [venueCode]: {lat, lng} }`, the lookup the engine's travel maths wants. */
export function venueCoords(venues) {
  const coords = new Map();
  for (const [code, venue] of venues) {
    if (venue.lat != null && venue.lng != null) coords.set(code, { lat: venue.lat, lng: venue.lng });
  }
  return coords;
}
/* The festival planner's stylesheet: the Fringe planner's, plus a theme.
 *
 * The page IS the Fringe planner's board, so it imports that stylesheet whole
 * rather than copying 1,600 lines that would then drift. Everything below is
 * either a brand token redefined, a rule the second festival's *shape* needs
 * (five columns rather than thirty-one), or a component this page has and the
 * Fringe planner doesn't (the browse stage, the trip links).
 *
 * Rebranding is the `:root` block: swap the five colours and the wordmark in
 * ./festival.js and the page is another festival's. Nothing below hard-codes
 * anything about Jerusalem except the comment saying where the colours came
 * from.
 */
@import url("../plan/plan.css");

:root {
  /* Jerusalem stone and the brass of the city's doors — the accent the Fringe
     planner spends on violet. Kept to the same two-tone shape (a mid tone and
     a darker one for hover/active) so every rule in plan.css that reaches for
     --violet lands somewhere sensible without being restated here. */
  --violet: #b8862b;
  --violet-dark: #94691d;
  --ink: #1d1a14;
  --bg: #faf7f0;
  --muted: #7a7160;
  --line: #ece5d8;

  /* The grid's palette, cut down to what this festival publishes: a night is on
     sale or it is free. The Fringe's sold-out / 2-for-1 / preview colours are
     left defined by the import and simply never drawn. */
  --fr-avail: #2a9d8f;
  --fr-free: #1f9e55;

  /* Hebrew: neither Inter nor Plus Jakarta Sans carries the script, so Heebo
     goes in front of both. A Latin string still renders in the site's own face
     — Heebo has no Latin coverage worth preferring, so the fallback order
     decides, which is what we want. */
  --sans: "Inter", "Heebo", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --display: "Plus Jakarta Sans", "Heebo", "Inter", system-ui, sans-serif;

  /* How many nights the grid spans. The Fringe planner's calendar is a fixed
     month; a festival's is exactly as long as its programme, and both the day
     header and every lane's track have to agree on the number. */
  --fest-days: 5;
}

/* Hebrew needs a little more line height than the Latin faces are set for, or
   the nikud-less but tall letters clip in the dense grid rows. */
[lang="he"] {
  font-family: "Heebo", var(--sans);
  line-height: 1.35;
}

/* A warm stone wash behind the page's top, so the festival reads as its own
   place without touching a single component. One gradient, no images. */
body.festival-page {
  background:
    linear-gradient(180deg, #f6ecd8 0%, rgba(246, 236, 216, 0) 420px),
    var(--bg);
}

/* --- the grid's shape ---------------------------------------------------- */

.days,
.lane-track {
  grid-template-columns: repeat(var(--fest-days), minmax(0, 1fr));
}

/* Both belong to the Fringe's month-long calendar: a pre-festival shaded zone
   and JS-positioned weekend stripes. This grid is only the festival's own
   nights, and the weekend is already marked on the day header. */
.wknd-cols,
.festend {
  display: none;
}

/* --- the browse stage ---------------------------------------------------- */

/* The Fringe planner's empty board asks for a favourites file. There is no such
   export for this festival, so the empty board is the programme itself — which
   at this size is a better starting point than a search box anyway. */
.browse-stage {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 14px 16px 6px;
  overflow: hidden;
}
.browse-head {
  flex: 0 0 auto;
}
.browse-line1 {
  margin: 0;
  font-family: var(--display);
  font-weight: 700;
  font-size: 1.05rem;
}
.browse-line2 {
  margin: 2px 0 0;
  font-size: 0.82rem;
  color: var(--muted);
}
.browse-list {
  flex: 1 1 auto;
  margin: 0;
  padding: 0 4px 8px 0;
  list-style: none;
  overflow-y: auto;
  overscroll-behavior: contain;
}

/* --- the trip links ------------------------------------------------------ */

/* The Fringe planner grows these as pop-up nags on the schedule's dead zones.
   Five nights leave no dead zone worth the trick, so they are one quiet row
   under the board — same question, same disclosure, less machinery. */
.trip-links {
  margin: 14px 0 0;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(184, 134, 43, 0.05);
}
.trip-links-title {
  margin: 0 0 8px;
  font-family: var(--display);
  font-weight: 700;
  font-size: 0.85rem;
}
.trip-links-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.trip-link {
  display: inline-flex;
  align-items: baseline;
  gap: 7px;
  padding: 7px 12px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: var(--paper);
  text-decoration: none;
  color: var(--ink);
  font-size: 0.82rem;
  font-weight: 600;
}
.trip-link:hover {
  border-color: var(--violet);
  color: var(--violet-dark);
}
.trip-link-partner {
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--muted);
}

/* --- the version popup --------------------------------------------------- */

/* Each front-end ships its own rules for the shared popup module (a stylesheet
   cannot be imported the way a module can) — except here, where the import
   above already brought the planner's in. Nothing to add. */

