// Renders one screen case to a PNG buffer — the single pixel source shared by
// the comparing runner (screen.test.js) and the refresh lane (refresh.js), so
// a golden can never be produced one way and checked another.
"use strict";

const { newPage, ORIGIN } = require("./harness/browser");
const { nowReady, planReady } = require("./case-helpers");
const { makeTools } = require("./capture-tools");

async function renderScreenCase(testCase) {
  const { page, context } = await newPage({
    viewport: testCase.viewport,
    localStorage: testCase.localStorage,
    geolocation: testCase.geolocation,
    failData: testCase.failData,
    timezone: testCase.timezone,
    advanceableClock: testCase.advanceableClock,
  });
  try {
    const pagePath = testCase.page || "/";
    await page.goto(`${ORIGIN}${pagePath}`, { waitUntil: "load" });
    if (testCase.ready) await testCase.ready(page);
    else if (pagePath.startsWith("/plan")) await planReady(page);
    else await nowReady(page);
    if (testCase.drive) await testCase.drive(page, { origin: ORIGIN });
    // Capture from a settled scroll position: drives that clicked through the
    // page may have left it part-scrolled (and mid-momentum), which skews
    // viewport→document rect conversion. Already-at-top pages fire no scroll
    // event here, so hover cards and popups survive.
    await page.evaluate(() => window.scrollTo(0, 0));
    await page.waitForTimeout(120);
    // The golden is the smallest surface that proves the leaf: a selector
    // (element crop), or a capture(page, tools) composing clips/stitches.
    // Whole-page capture is the deliberate exception, not the default.
    if (typeof testCase.capture === "string") {
      // Clip at the element's box rather than element.screenshot(): a clip
      // never scrolls, so a hover card or popup can't be dismissed mid-shot.
      const tools = makeTools(page);
      return await tools.element(testCase.capture);
    }
    if (typeof testCase.capture === "function") {
      return await testCase.capture(page, makeTools(page));
    }
    return await page.screenshot({ fullPage: !testCase.viewportOnly, animations: "disabled" });
  } finally {
    await context.close();
  }
}

module.exports = { renderScreenCase };
// The registry of requirement KINDS — the framework's single extension point.
// A "kind" is one way a requirement leaf can be asserted (a rendered screen, a
// driven gesture, a pure rule). Kinds are AUTO-DISCOVERED: every
// product/requirements/<kind>/ directory containing a `kind.js` descriptor is a
// kind, named for its folder. The folder IS the classifier — a case's kind is
// the directory it lives in, never a field inside the case.
//
// Adding a kind is a self-contained folder drop:
//   1. mkdir product/requirements/<kind>/cases
//   2. add product/requirements/<kind>/kind.js  ({ image: <bool> })
//   3. add the kind's runner (wired into the right test lane)
//   4. add the leaf(s) to product/requirements.md and a case under cases/
// Nothing here, in the loader, or in the coverage gate needs editing — they all
// iterate this registry.
"use strict";

const fs = require("node:fs");
const path = require("node:path");

const REQUIREMENTS_DIR = path.join(__dirname, "..");

function loadKinds() {
  return fs
    .readdirSync(REQUIREMENTS_DIR, { withFileTypes: true })
    .filter((d) => d.isDirectory() && fs.existsSync(path.join(REQUIREMENTS_DIR, d.name, "kind.js")))
    .map((d) => {
      const descriptor = require(path.join(REQUIREMENTS_DIR, d.name, "kind.js"));
      return {
        name: d.name,
        // image = the kind's owner-approved expected is a committed PNG golden;
        // a non-image kind's expected is a coded assertion and its folder must
        // carry no PNG (enforced by the coverage gate).
        image: Boolean(descriptor.image),
        dir: path.join(REQUIREMENTS_DIR, d.name),
        casesDir: path.join(REQUIREMENTS_DIR, d.name, "cases"),
      };
    })
    .sort((a, b) => a.name.localeCompare(b.name));
}

const KINDS = loadKinds();
const KIND_NAMES = KINDS.map((k) => k.name);
const IMAGE_KINDS = KINDS.filter((k) => k.image).map((k) => k.name);

module.exports = { KINDS, KIND_NAMES, IMAGE_KINDS };
// The behavior kind's runner: each case drives a real page in the harness and
// asserts the gesture's consequence in code — the coded assertions ARE the
// owner-approved expected, so they are never weakened to pass. Runs in the
// `test:ui` lane. Self-asserts that it covers exactly the behavior cases.
"use strict";

const { test, after } = require("node:test");
const assert = require("node:assert/strict");
const { loadCases } = require("../shared/cases");
const { newPage, closeBrowser, ORIGIN } = require("../shared/harness/browser");

const CASES = loadCases().filter((c) => c.kind === "behavior");

test("there is at least one behavior case", () => {
  assert.ok(CASES.length > 0, "no behavior cases found");
});

test("every behavior case declares a verify()", () => {
  const bad = CASES.filter((c) => typeof c.verify !== "function").map((c) => c.name);
  assert.deepEqual(bad, [], "behavior cases without a verify():");
});

for (const testCase of CASES) {
  test(`behavior "${testCase.name}" (${testCase.description})`, async () => {
    const { page, context } = await newPage({
      viewport: testCase.viewport,
      localStorage: testCase.localStorage,
      geolocation: testCase.geolocation,
      failData: testCase.failData,
    });
    try {
      await testCase.verify(page, { origin: ORIGIN, context, assert });
    } finally {
      await context.close();
    }
  });
}

after(async () => {
  await closeBrowser();
});

