export function pluralCategoriesOf(message) {
  const found = new Map();
  const re = /\{\s*([a-zA-Z0-9_]+)\s*,\s*plural\s*,/g;
  for (const m of message.matchAll(re)) {
    const { cases } = parseCategories(message, m.index + m[0].length);
    found.set(m[1], new Set(cases.keys()));
  }
