p = "planJerusalem/planJerusalem.css"
s = open(p, encoding="utf-8").read()
old_root_start = s.index(":root {")
old_root_end = s.index("}", s.index("--fest-days: 5;")) + 1
new_root = ''':root {
  /* Light and dark in one declaration each: `color-scheme: light dark` tells
     the browser both exist (which also darkens the native select and time
