input.command:
python3 - <<'PY'
p = "planJerusalem/planJerusalem.css"
s = open(p, encoding="utf-8").read()
marker = '''/* --- the version popup --------------------------------------------------- */'''
assert s.count(marker) == 1
addition = '''/* --- the reader's own two controls ---------------------------------------- */

/* Language and theme sit at the end of the header, after the festival's dates:
   they belong to the reader rather than to the festival, so they read as the
   last thing in the bar rather than as part of its identity. */
.chrome-prefs {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-inline-start: 10px;
}
.lang-select {
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--paper);
  color: var(--ink);
  font: inherit;
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
}
.lang-select:hover,
.theme-toggle:hover {
  border-color: var(--violet);
  color: var(--violet-dark);
}
.theme-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--paper);
  color: var(--ink);
  cursor: pointer;
}
/* The toggle shows the state a press would move to, which is the opposite of
   the one in force — so the icons swap with the theme, on the reader's choice
   or (with no choice made) on the device's. */
.theme-ico--sun {
  display: none;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) .theme-ico--sun {
    display: block;
  }
  :root:not([data-theme="light"]) .theme-ico--moon {
    display: none;
  }
}
:root[data-theme="dark"] .theme-ico--sun {
  display: block;
}
:root[data-theme="dark"] .theme-ico--moon {
  display: none;
}

/* What the failed fetch actually said, under the line that says it failed.
   Untranslated on purpose — it is the network's words, not ours. */
.state-tech {
  margin: 4px 0 0;
  font-size: 0.78rem;
  color: var(--muted);
}

/* --- the components the Fringe planner paints white ----------------------- */

/* plan.css was written for one theme and spells those surfaces `#fff`. They are
   restated here against the token, which carries both themes, rather than
   duplicated into a dark-only block — a rule that reads the same in the light
   is a rule that cannot drift between the two. */
.site-header {
  background: color-mix(in srgb, var(--paper) 95%, transparent);
}
.board-clear,
.btn-ghost,
.board-legend-btn,
.ss-bar,
.chip-trigger,
.panel-filter,
.opt-select,
.ctl-time,
.ctl-num,
.tmode,
.tmode-btn,
.meal-pill,
.win-flag,
.sch-show,
.sch-pin,
.sch-emoji {
  background: var(--paper);
}
.schedule-wrap {
  background:
    linear-gradient(var(--paper), var(--paper)) padding-box,
    repeating-linear-gradient(90deg, color-mix(in srgb, var(--ink) 4%, var(--paper)) 0 1px, transparent 1px 100%)
      padding-box;
}
.sch-day--empty {
  background: repeating-linear-gradient(
    45deg,
    color-mix(in srgb, var(--ink) 4%, var(--paper)) 0 5px,
    color-mix(in srgb, var(--ink) 8%, var(--paper)) 5px 10px
  );
}
.browse-list .ss-row,
.ss-results .ss-row {
  color: var(--ink);
}

/* --- right to left -------------------------------------------------------- */

/* The board's own geometry follows the page's direction on its own: the day
   columns, the lanes and the schedule's days are grid and flex tracks, and the
   date window's overlay is mirrored in planJerusalem.js. What is left here is
   the handful of places plan.css states a physical side. */
[dir="rtl"] .ss-icon {
  left: auto;
  right: 12px;
}
[dir="rtl"] .ss-input {
  padding-left: 12px;
  padding-right: 40px;
}
[dir="rtl"] .sch-show {
  border-left: 0;
  border-right: 4px solid currentColor;
}
[dir="rtl"] .sch-emoji {
  left: auto;
  right: -2px;
  transform: translate(50%, -50%);
}
[dir="rtl"] .lane-remove {
  right: auto;
  left: 4px;
}
[dir="rtl"] .win-handle--start .win-flag {
  transform: translateX(50%);
}
[dir="rtl"] .win-handle--end .win-flag {
  transform: translateX(-50%);
}

''' + marker
s = s.replace(marker, addition)
open(p, "w", encoding="utf-8").write(s)
print("ok")
PY
