SP=/tmp/claude-0/-home-user-EdFringeNow/d53e5df5-b616-511d-9382-f227d8ba765a/scratchpad; cat > "$SP/shot.mjs" <<'EOF'
// One driver for every look at the page: node shot.mjs <url> <out.png> [k=v ...]
//   w=1280 h=900 scheme=dark star=1 full=1 sel=.site-header
import { chromium } from "/opt/node22/lib/node_modules/playwright/index.mjs";

const [url, out, ...rest] = process.argv.slice(2);
const opt = Object.fromEntries(rest.map((a) => a.split("=")));
const STARRED = ["opening", "poetry-slam", "salakh", "late", "king", "yona-kapach", "neighbor"];

const browser = await chromium.launch({ args: ["--font-render-hinting=none", "--hide-scrollbars"] });
const context = await browser.newContext({
  viewport: { width: Number(opt.w || 1280), height: Number(opt.h || 900) },
  deviceScaleFactor: 1,
  colorScheme: opt.scheme || "light",
});
const page = await context.newPage();
if (opt.star) {
  await page.addInitScript(`localStorage.setItem("jerusalemPlan.starred", ${JSON.stringify(JSON.stringify(STARRED))});`);
}
const errors = [];
page.on("pageerror", (e) => errors.push("pageerror: " + e.message));
page.on("console", (m) => { if (m.type() === "error") errors.push("console: " + m.text()); });
await page.goto(url, { waitUntil: "load" });
await page.waitForSelector("#browseList .ss-row, #lanes .lane", { state: "attached", timeout: 15000 }).catch(() => {});
await page.evaluate(() => document.fonts.ready);
await page.waitForTimeout(600);
if (opt.sel) await page.locator(opt.sel).screenshot({ path: out });
else await page.screenshot({ path: out, fullPage: !!opt.full });
console.log(errors.filter((e) => !/favicon|ERR_CONNECTION_RESET/.test(e)).join("\n") || "no page errors");
await browser.close();
EOF
