p = "planJerusalem/planJerusalem.css"
s = open(p, encoding="utf-8").read()
def sub(old, new):
    global s
    assert s.count(old) == 1, old[:70]
    s = s.replace(old, new)

sub('''  --shadow-soft: light-dark(0 12px 30px rgba(16, 24, 40, 0.08), 0 12px 30px rgba(0, 0, 0, 0.55));''',
'''  --shadow-soft: light-dark(0 12px 30px rgba(16, 24, 40, 0.08), 0 12px 30px rgba(0, 0, 0, 0.55));
  /* The "in your plan" pill, which plan.css paints as ink-on-wash. */
  --ok-text: light-dark(#047857, #6fe0ab);
  --ok-bg: light-dark(#e6f7ee, #123527);''')

sub('''.browse-list .ss-row,
.ss-results .ss-row {
  color: var(--ink);
}''',
'''.browse-list .ss-row,
.ss-results .ss-row {
  color: var(--ink);
}
/* The footer is the one band that is dark in both themes, so it cannot follow
   --ink (which flips) and states its own two. */
.site-footer {
  background: light-dark(#1d1a14, #0a0906);
  color: light-dark(#d9d9d9, #b6ac99);
}
.sch-day--empty .sch-day-head {
  background: color-mix(in srgb, var(--ink) 4%, var(--paper));
}
.sch-day.wknd .sch-day-head {
  background: color-mix(in srgb, var(--violet) 8%, var(--paper));
}''')
open(p, "w", encoding="utf-8").write(s)
print("ok")
PY
