// What each budgeted key's slot can actually afford, and what each language
// asks of it — the numbers behind the maxWidthPx column.
import { createRequire } from "node:module";
const require = createRequire("/home/user/EdFringeNow/product/requirements/");
const { newPage, closeBrowser, ORIGIN, VIEWPORTS } = require("/home/user/EdFringeNow/product/requirements/shared/harness/browser.js");
const { jerusalemReady, jerusalemStarred } = require("/home/user/EdFringeNow/product/requirements/shared/case-helpers.js");
const { STRINGS, LOCALES } = await import("/home/user/EdFringeNow/planJerusalem/i18n/translations.js");
const { format, argumentsOf } = await import("/home/user/EdFringeNow/planJerusalem/i18n/format.js");

const { page, context } = await newPage({ viewport: "desktop", localStorage: jerusalemStarred() });
await page.goto(`${ORIGIN}/planJerusalem/`, { waitUntil: "load" });
await jerusalemReady(page);
const budgeted = Object.entries(STRINGS).filter(([, e]) => e.maxWidthPx !== null);
const report = new Map(budgeted.map(([k]) => [k, { slot: {}, widest: 0, worst: "" }]));

for (const [vp, size] of Object.entries(VIEWPORTS)) {
  await page.setViewportSize(size);
  for (const { code } of LOCALES) {
    await page.selectOption("#langSelect", code);
    await page.waitForFunction((c) => document.documentElement.lang === c, code);
    await page.evaluate(() => document.fonts.ready);
    const items = budgeted.map(([key, e]) => {
      const sample = e.sample || {};
      const params = Object.fromEntries([...argumentsOf(e[code])].map((a) => [a, sample[a] ?? 12]));
      return { key, probe: e.probe || null, text: format(e[code], params, code) };
    });
    const out = await page.evaluate((entries) => {
      const slots = new Map();
      for (const el of document.querySelectorAll("*"))
        for (const [n, v] of Object.entries(el.dataset))
          if (n.startsWith("i18n") && !slots.has(v)) slots.set(v, el);
      const probe = document.createElement("span");
      probe.style.cssText = "position:absolute;top:-9999px;left:-9999px;visibility:hidden;white-space:pre";
      probe.lang = document.documentElement.lang;
      document.body.appendChild(probe);
      const P = ["font-family","font-size","font-weight","font-style","font-stretch","font-variant","font-feature-settings","font-kerning","letter-spacing","word-spacing","text-transform"];
      return entries.map((e) => {
        const slot = slots.get(e.key) || (e.probe && document.querySelector(e.probe));
        if (!slot) return { key: e.key, width: null, slotWidth: null };
        const cs = getComputedStyle(slot);
        for (const p of P) probe.style.setProperty(p, cs.getPropertyValue(p));
        probe.textContent = e.text;
        // what the slot's own box offers: its content width, or its parent's
        // when the slot is an inline element with no box of its own
        const own = slot.getBoundingClientRect().width;
        const parent = slot.parentElement ? slot.parentElement.getBoundingClientRect().width : own;
        return { key: e.key, width: probe.getBoundingClientRect().width, slotWidth: Math.max(own, 0), parentWidth: parent, wraps: cs.whiteSpace !== "nowrap" && cs.display !== "inline-block" };
      });
    }, items);
    out.forEach((m, i) => {
      const r = report.get(m.key);
      r.slot[vp] = m.slotWidth === null ? null : { own: Math.round(m.slotWidth), parent: Math.round(m.parentWidth), wraps: m.wraps };
      if (m.width > r.widest) { r.widest = m.width; r.worst = `${code}/${vp}`; }
    });
  }
}
console.log("key\tbudget\twidest\tworst\tdesktopSlot\tmobileSlot\twraps");
for (const [key, r] of report) {
  const d = r.slot.desktop, m = r.slot.mobile;
  console.log([key, STRINGS[key].maxWidthPx, Math.round(r.widest), r.worst,
    d ? `${d.own}/${d.parent}` : "-", m ? `${m.own}/${m.parent}` : "-", d ? d.wraps : "-"].join("\t"));
}
await context.close();
await closeBrowser();
EOF
