p="planJerusalem/planJerusalem.css"
s=open(p,encoding="utf-8").read()
def sub(old,new):
    global s
    assert s.count(old)==1, old[:60]
    s=s.replace(old,new)

sub('''  /* Light and dark in one declaration each: `color-scheme: light dark` tells
     the browser both exist (which also darkens the native select and time
     fields), and every token below picks its side with `light-dark()`. The
     reader's own choice, when they make one, narrows the scheme to one side —
     see [data-theme] below — so there is exactly one place per token where a
     colour is written, rather than a whole second palette to keep in step. */
  color-scheme: light dark;

''','''''')

sub('''/* A reader who has chosen pins the scheme to one side; with no choice made the
   declaration above leaves it to the device. */
:root[data-theme="light"] {
  color-scheme: only light;
}
:root[data-theme="dark"] {
  color-scheme: only dark;
}''',
'''/* Every colour above picks its side with `light-dark()`, which reads the used
   colour scheme — so the whole dark theme is these two rules: the device asks
   for dark and the reader has not said otherwise, or the reader chose it. Light
   declares nothing, deliberately: `color-scheme` shifts how the page's own
   background composites by a unit per channel, and the light rendering is
   committed in the goldens. Declaring it only on the dark side also darkens the
   native select and time fields there, which is the rest of what it is for. */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
  }
}
:root[data-theme="dark"] {
  color-scheme: dark;
}''')

sub('''/* Spelled twice rather than with light-dark(), which is what every other
   colour here uses: a gradient interpolating towards transparent rounds a
   channel differently when its stops come from that function, and the light
   half of this one is committed in the goldens to the byte. */
body.festival-page {
  background:
    linear-gradient(180deg, #f6ecd8 0%, rgba(246, 236, 216, 0) 420px),
    var(--bg);
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) body.festival-page {
    background:
      linear-gradient(180deg, #241d12 0%, rgba(36, 29, 18, 0) 420px),
      var(--bg);
  }
}
:root[data-theme="dark"] body.festival-page {
  background:
    linear-gradient(180deg, #241d12 0%, rgba(36, 29, 18, 0) 420px),
    var(--bg);
}''',
'''body.festival-page {
  background:
    linear-gradient(
      180deg,
      light-dark(#f6ecd8, #241d12) 0%,
      light-dark(rgba(246, 236, 216, 0), rgba(36, 29, 18, 0)) 420px
    ),
    var(--bg);
}''')
open(p,"w",encoding="utf-8").write(s)
print("ok")
PY
